typedef long long ll;

int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);
  int n;
  cin >> n;
  vector<int> h(n);
  for (int i = 0; i < n; ++i) cin >> h[i];
  vector<vector<int>> g(n);
  for (int i = 0; i + 1 < n; ++i) {
    int u, v;
    cin >> u >> v;
    --u, --v;
    g[u].push_back(v);
    g[v].push_back(u);
  }
  int rt = 0;
  for (int i = 0; i < n; ++i) {
    if (h[i] > h[rt]) {
      rt = i;
    }
  }
  ll ans = 0;
  function<int(int, int)> dfs = [&](int u, int p) {
    int mx1 = 0, mx2 = 0;
    vector<int> have;
    for (auto v : g[u]) {
      if (v != p) {
        int cur = dfs(v, u);
        if (cur > mx1) swap(cur, mx1);
        if (cur > mx2) swap(cur, mx2);
      }
    }
    if (p != -1) {
      int delta = max(0, h[u] - mx1);
      ans += delta;
      mx1 += delta;
    } else {
      ans += max(0, h[u] - mx1) + max(0, h[u] - mx2);
    }
    return mx1;
  };
  dfs(rt, -1);
  cout << ans << '\n';
}

#include <bits/stdc++.h>
using namespace std;

vector<pair<int, int>> ops;
vector<int> a;

void rec(int n, int coeff) {
    if (n <= 2) {
        for (int i = 1; i <= n; i++)
            a.push_back(i * coeff);
        return;
    }

    int p = 1;
    while (p * 2 <= n) p *= 2;

    if (p == n) {
        a.push_back(n * coeff);
        n--, p /= 2;
    }

    a.push_back(p * coeff);
    for (int i = p + 1; i <= n; i++) {
        a.push_back(2 * p * coeff);
        ops.emplace_back(i * coeff, (2 * p - i) * coeff);
    }

    rec(2 * p - n - 1, coeff);
    rec(n - p, coeff * 2);
}

void solve() {
    int n;
    cin >> n;
    if (n == 2) {
        cout << "-1\n";
        return;
    }

    ops.clear();
    a.clear();
    rec(n, 1);
    sort(a.begin(), a.end());

    int answer = 1;
    while (answer < n)
        answer *= 2;

    for (int i = 0;; i++)
        if (a[i] == a[i + 1]) {
            assert(a[i] != answer);
            ops.emplace_back(a[i], a[i]);
            a[i + 1] *= 2;
            a.erase(a.begin() + i);
            break;
        }

    for (auto x : a)
        while (x != answer) {
            ops.emplace_back(0, x);
            ops.emplace_back(x, x);
            x *= 2;
        }

    ops.emplace_back(0, answer);
    cout << ops.size() << '\n';
    for (auto &[x, y] : ops)
        cout << x << ' ' << y << '\n';
}

int main() {
    int tests;
    cin >> tests;
    while (tests--)
        solve();
}

#include <bits/stdc++.h>
using namespace std;

struct binary_index_tree {
    int n;
    vector<int> bit;

    binary_index_tree(int n) : n(n), bit(n + 1) {}

    void increase(int pos) {
        for (pos++; pos <= n; pos += pos & -pos)
            bit[pos]++;
    }

    int query(int pref) const {
        int sum = 0;
        for (; pref; pref -= pref & -pref)
            sum += bit[pref];

        return sum;
    }
};

void solve() {
    int n;
    cin >> n;

    vector<int> d(n);
    binary_index_tree bit(n);
    long long inversions = 0;

    for (int i = 0; i < n; i++) {
        int p;
        cin >> p;
        p--;

        d[i] = i - 2 * p;
        inversions += i - bit.query(p);
        bit.increase(p);
    }
    sort(d.rbegin(), d.rend());

    cout << inversions;
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        sum += d[i];
        cout << ' ' << inversions - sum - 1ll * i * (i + 1) / 2;
    }

    cout << '\n';
}

int main() {
    ios::sync_with_stdio(false), cin.tie(nullptr);

    int tests;
    cin >> tests;
    while (tests--)
        solve();
}
